import { parse } from "yaml";
import { marked } from "marked";

export type Book = {
  slug: string;
  title: string;
  author: string;
  year: number;
  rating: number;
  tags: string[];
  html: string;
};

const files = import.meta.glob("../../content/books/*.md", {
  eager: true,
  query: "?raw",
  import: "default"
}) as Record<string, string>;

function load(path: string, raw: string): Book {
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(raw);
  const data = (m ? parse(m[1]) : {}) as Record<string, any>;
  return {
    slug: path.split("/").pop()!.replace(/\.md$/, ""),
    title: String(data.title),
    author: String(data.author),
    year: Number(data.year),
    rating: Number(data.rating),
    tags: (data.tags ?? []).map(String),
    html: marked.parse(m ? m[2] : raw, { async: false }) as string
  };
}

const cmp = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);

export const books: Book[] = Object.entries(files)
  .map(([p, r]) => load(p, r))
  .sort((a, b) => cmp(a.title, b.title));

export const topRated = () =>
  [...books].sort((a, b) => b.rating - a.rating || cmp(a.title, b.title)).slice(0, 3);

export const allTags = () => [...new Set(books.flatMap(b => b.tags))].sort(cmp);

export const getBook = (slug: string) => books.find(b => b.slug === slug);
