import { getRequestEvent } from "solid-js/web";
import { validate } from "./contact";

const str = (d: FormData, k: string) => String(d.get(k) ?? "").trim();

export async function submission() {
  "use server";
  const req = getRequestEvent()?.request;
  if (!req || req.method !== "POST") return null;
  const ct = req.headers.get("content-type") ?? "";
  if (!ct.includes("form")) return null;
  const d = await req.formData();
  return result({ name: str(d, "name"), email: str(d, "email"), message: str(d, "message") });
}

export async function send(name: string, email: string, message: string) {
  "use server";
  return result({ name: name.trim(), email: email.trim(), message: message.trim() });
}

function result(values: { name: string; email: string; message: string }) {
  const errors = validate(values);
  return { values, errors, ok: Object.keys(errors).length === 0 };
}
