          <a href="/about" aria-current={cur("/about")}>About</a>
          <a href="/contact" aria-current={cur("/contact")}>Contact</a>
        </nav>
      </header>
      <main>
        <Suspense>{props.children}</Suspense>
      </main>
      <footer>© Bookshelf</footer>
    </>
  );
}

export default function App() {
  return (
    <Router root={props => <MetaProvider><Layout>{props.children}</Layout></MetaProvider>}>
      <FileRoutes />
    </Router>
  );
}
