cat > routes/contact.tsx <<'EOF'
import { Title } from "@solidjs/meta";
import { createAsync } from "@solidjs/router";
import { Show, createEffect, createSignal } from "solid-js";
import { validate, type Errors } from "~/lib/contact";
import { send, submission } from "~/lib/contact.server";

export default function Contact() {
  const initial = createAsync(() => submission(), { deferStream: true });
  const [errors, setErrors] = createSignal<Errors>({});
  const [done, setDone] = createSignal<string | null>(null);
  const [vals, setVals] = createSignal({ name: "", email: "", message: "" });

  createEffect(() => {
    const s = initial();
    if (!s) return;
    setVals(s.values);
    setErrors(s.errors);
    setDone(s.ok ? s.values.name : null);
  });

  async function onSubmit(e: SubmitEvent) {
    e.preventDefault();
    const d = new FormData(e.currentTarget as HTMLFormElement);
    const v = {
      name: String(d.get("name") ?? "").trim(),
      email: String(d.get("email") ?? "").trim(),
      message: String(d.get("message") ?? "").trim()
    };
    setVals(v);
    const errs = validate(v);
    setErrors(errs);
    setDone(null);
    if (Object.keys(errs).length) return;
    const r = await send(v.name, v.email, v.message);
    setErrors(r.errors);
    if (r.ok) setDone(r.values.name);
  }

  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={done() !== null}>
        <p>Thanks, {done()}! Your message has been sent.</p>
      </Show>
      <form method="post" action="/contact" novalidate onSubmit={onSubmit}>
        <div>
          <label for="name">Name</label>
          <input id="name" name="name" type="text" value={vals().name} />
          <Show when={errors().name}><span>{errors().name}</span></Show>
        </div>
        <div>
          <label for="email">Email</label>
          <input id="email" name="email" type="email" value={vals().email} />
          <Show when={errors().email}><span>{errors().email}</span></Show>
        </div>
        <div>
          <label for="message">Message</label>
          <textarea id="message" name="message" value={vals().message} />
          <Show when={errors().message}><span>{errors().message}</span></Show>
        </div>
        <button type="submit">Send</button>
      </form>
    </>
  );
}
EOF
